insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('original-resumes','original-resumes',false,5242880,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain']),('tailored-resumes','tailored-resumes',false,5242880,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "owners select resume objects" on storage.objects for select to authenticated using(bucket_id in('original-resumes','tailored-resumes') and (storage.foldername(name))[1]=(select auth.uid()::text));create policy "owners insert resume objects" on storage.objects for insert to authenticated with check(bucket_id in('original-resumes','tailored-resumes') and (storage.foldername(name))[1]=(select auth.uid()::text));create policy "owners update resume objects" on storage.objects for update to authenticated using(bucket_id in('original-resumes','tailored-resumes') and (storage.foldername(name))[1]=(select auth.uid()::text)) with check(bucket_id in('original-resumes','tailored-resumes') and (storage.foldername(name))[1]=(select auth.uid()::text));create policy "owners delete resume objects" on storage.objects for delete to authenticated using(bucket_id in('original-resumes','tailored-resumes') and (storage.foldername(name))[1]=(select auth.uid()::text));
